let particles = [];
let interactions = [];
let currentScene = 0;
let sceneTimer = 0;
let sceneDuration = 500;
let fontLoaded = false;

function setup() {
  createCanvas(windowWidth, windowHeight);
  textFont('Arial');
  initScene(0);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initScene(currentScene);
}

function initScene(index) {
  particles = [];
  interactions = [];
  currentScene = index;
  sceneTimer = 0;
  let cx = width / 2;
  let cy = height / 2;

  if (index === 0) {
    particles.push(new Fermion(cx - 140, cy, 'electron', -1, '#2563eb', 0.511));
    particles.push(new Fermion(cx + 140, cy, 'proton', +1, '#dc2626', 938.0));
  } else if (index === 1) {
    particles.push(new Fermion(cx - 90, cy - 70, 'up', 0.666, '#ef4444', 2.2));
    particles.push(new Fermion(cx + 90, cy - 70, 'up', 0.666, '#3b82f6', 2.2));
    particles.push(new Fermion(cx, cy + 90, 'down', -0.333, '#10b981', 4.7));
  } else if (index === 2) {
    particles.push(new Fermion(cx, cy, 'neutron', 0, '#4b5563', 939.6));
  }
}

function draw() {
  background(250, 248, 245);

  sceneTimer++;
  if (sceneTimer > sceneDuration) {
    initScene((currentScene + 1) % 3);
  }

  drawInterface();

  if (currentScene === 0) updateElectromagnetic();
  else if (currentScene === 1) updateStrongForce();
  else if (currentScene === 2) updateWeakForce();

  for (let p of particles) {
    p.update();
    p.display();
  }

  for (let i = interactions.length - 1; i >= 0; i--) {
    interactions[i].update();
    interactions[i].display();
    if (interactions[i].finished()) interactions.splice(i, 1);
  }
}

function drawInterface() {
  push();
  textAlign(CENTER, TOP);
  fill(30);
  noStroke();

  textSize(28);
  textStyle(BOLD);
  let titles = [
    "Electromagnetic Interaction",
    "Strong Nuclear Force", 
    "Weak Nuclear Force"
  ];
  text(titles[currentScene], width/2, 30);

  textSize(15);
  textStyle(NORMAL);
  fill(80);
  let descs = [
    "Charged particles exchange photons (γ)",
    "Quarks exchange gluons, creating color confinement",
    "Neutron decay via W⁻ boson emission (β⁻ decay)"
  ];
  text(descs[currentScene], width/2, 65);

  stroke(200);
  strokeWeight(2);
  noFill();
  rect(width/2 - 100, height - 35, 200, 6, 3);

  noStroke();
  fill(100, 150, 255);
  rect(width/2 - 100, height - 35, map(sceneTimer, 0, sceneDuration, 0, 200), 6, 3);
  pop();
}

function updateElectromagnetic() {
  let time = frameCount * 0.025;
  particles[0].setTarget(width/2 - 140 + cos(time) * 15, height/2 + sin(time) * 15);
  particles[1].setTarget(width/2 + 140 + cos(time + PI) * 15, height/2 + sin(time + PI) * 15);

  if (frameCount % 100 === 0) {
    interactions.push(new PhotonExchange(particles[0], particles[1]));
  }
}

function updateStrongForce() {
  let time = frameCount * 0.035;
  let cx = width/2, cy = height/2;

  particles[0].setTarget(cx - 100 + cos(time) * 25, cy - 50 + sin(time * 1.2) * 25);
  particles[1].setTarget(cx + 100 + cos(time + TWO_PI/3) * 25, cy - 50 + sin(time * 1.2 + TWO_PI/3) * 25);
  particles[2].setTarget(cx + cos(time + 2*TWO_PI/3) * 25, cy + 80 + sin(time * 1.2 + 2*TWO_PI/3) * 25);

  if (frameCount % 70 === 0) {
    let a = floor(random(3));
    let b = (a + 1 + floor(random(2))) % 3;
    interactions.push(new GluonExchange(particles[a], particles[b]));
  }
}

function updateWeakForce() {
  if (sceneTimer === 150 && particles[0].type === 'neutron') {
    particles[0].type = 'proton';
    particles[0].charge = 1;
    particles[0].color = '#dc2626';
    particles[0].mass = 938.3;

    let cx = width/2, cy = height/2;
    let elec = new Fermion(cx, cy, 'electron', -1, '#2563eb', 0.511);
    elec.vx = -4; elec.vy = -3;
    particles.push(elec);

    let neutrino = new Fermion(cx, cy, 'e-neutrino', 0, '#16a34a', 0.000002);
    neutrino.vx = 3; neutrino.vy = -2.5;
    particles.push(neutrino);

    interactions.push(new WBoson(particles[0], elec));
  }

  for (let i = 1; i < particles.length; i++) {
    particles[i].x += particles[i].vx;
    particles[i].y += particles[i].vy;
    particles[i].vx *= 0.99;
    particles[i].vy *= 0.99;
  }
}

class Fermion {
  constructor(x, y, type, charge, col, mass) {
    this.x = x;
    this.y = y;
    this.targetX = x;
    this.targetY = y;
    this.type = type;
    this.charge = charge;
    this.color = col;
    this.mass = mass;
    this.vx = 0;
    this.vy = 0;
    this.pulse = random(TWO_PI);
    this.trail = [];
  }

  setTarget(tx, ty) {
    this.targetX = tx;
    this.targetY = ty;
  }

  update() {
    this.x += (this.targetX - this.x) * 0.08;
    this.y += (this.targetY - this.y) * 0.08;
    this.pulse += 0.08;

    this.trail.push({x: this.x, y: this.y});
    if (this.trail.length > 8) this.trail.shift();
  }

  display() {
    push();

    if (this.trail.length > 1) {
      noFill();
      stroke(red(this.color), green(this.color), blue(this.color), 40);
      strokeWeight(8);
      beginShape();
      for (let pos of this.trail) vertex(pos.x, pos.y);
      endShape();
    }

    translate(this.x, this.y);

    drawingContext.shadowBlur = 25;
    drawingContext.shadowColor = this.color;

    noStroke();
    fill(this.color);
    let r = 28 + sin(this.pulse) * 3;
    ellipse(0, 0, r * 2);

    drawingContext.shadowBlur = 0;

    fill(255, 90);
    ellipse(-r*0.25, -r*0.25, r * 0.9);

    fill(255);
    textAlign(CENTER, CENTER);
    textSize(11);
    textStyle(BOLD);
    let label = this.type === 'e-neutrino' ? 'νₑ' : 
                this.type === 'up' ? 'u' : 
                this.type === 'down' ? 'd' : 
                this.type.charAt(0).toUpperCase();
    text(label, 0, -2);

    fill(40);
    textSize(9);
    let cstr = this.charge > 0 ? '+' + nf(this.charge, 1, 2) : 
               this.charge < 0 ? nf(this.charge, 1, 2) : '0';
    text(cstr + 'e', 0, r + 12);

    pop();
  }
}

class PhotonExchange {
  constructor(p1, p2) {
    this.p1 = p1;
    this.p2 = p2;
    this.t = 0;
    this.speed = 0.025;
    this.waveOffset = random(100);
  }

  update() {
    this.t += this.speed;
  }

  display() {
    let x = lerp(this.p1.x, this.p2.x, this.t);
    let y = lerp(this.p1.y, this.p2.y, this.t);

    push();
    stroke(250, 180, 30);
    strokeWeight(3);
    noFill();

    let dx = this.p2.x - this.p1.x;
    let dy = this.p2.y - this.p1.y;
    let len = sqrt(dx*dx + dy*dy);
    let nx = -dy/len;
    let ny = dx/len;

    beginShape();
    for (let i = 0; i <= 20; i++) {
      let tt = i/20;
      let px = lerp(this.p1.x, this.p2.x, tt);
      let py = lerp(this.p1.y, this.p2.y, tt);
      let wave = sin(tt * PI * 6 + this.waveOffset) * 6;
      vertex(px + nx * wave, py + ny * wave);
    }
    endShape();

    fill(255, 220, 50);
    noStroke();
    ellipse(x, y, 14);

    fill(200, 150, 20);
    textAlign(CENTER, CENTER);
    textSize(10);
    text('γ', x, y);
    pop();
  }

  finished() {
    return this.t >= 1;
  }
}

class GluonExchange {
  constructor(p1, p2) {
    this.p1 = p1;
    this.p2 = p2;
    this.t = 0;
    this.speed = 0.03;
    this.hue = random(['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff']);
  }

  update() {
    this.t += this.speed;
  }

  display() {
    push();
    let dx = this.p2.x - this.p1.x;
    let dy = this.p2.y - this.p1.y;
    let len = sqrt(dx*dx + dy*dy);
    let nx = -dy/len;
    let ny = dx/len;

    stroke(200, 60, 60);
    strokeWeight(4);
    noFill();

    beginShape();
    for (let i = 0; i <= 30; i++) {
      let tt = i/30 * this.t;
      let px = lerp(this.p1.x, this.p2.x, tt);
      let py = lerp(this.p1.y, this.p2.y, tt);
      let coil = sin(tt * PI * 8) * 10 * (1 - tt * 0.5);
      vertex(px + nx * coil, py + ny * coil);
    }
    endShape();

    let x = lerp(this.p1.x, this.p2.x, this.t);
    let y = lerp(this.p1.y, this.p2.y, this.t);

    fill(220, 80, 80);
    noStroke();
    ellipse(x, y, 12);

    fill(255);
    textAlign(CENTER, CENTER);
    textSize(9);
    text('g', x, y);
    pop();
  }

  finished() {
    return this.t >= 1;
  }
}

class WBoson {
  constructor(source, target) {
    this.x = source.x;
    this.y = source.y;
    this.targetX = (source.x + target.x) / 2;
    this.targetY = (source.y + target.y) / 2 - 50;
    this.life = 80;
    this.maxLife = 80;
  }

  update() {
    this.x += (this.targetX - this.x) * 0.15;
    this.y += (this.targetY - this.y) * 0.15;
    this.life--;
  }

  display() {
    push();
    translate(this.x, this.y);

    let alpha = map(this.life, 0, this.maxLife, 0, 255);
    fill(147, 51, 234, alpha);
    stroke(100, 30, 180, alpha);
    strokeWeight(2);

    beginShape();
    vertex(0, -14);
    vertex(10, 0);
    vertex(0, 14);
    vertex(-10, 0);
    endShape(CLOSE);

    fill(255, alpha);
    noStroke();
    textAlign(CENTER, CENTER);
    textSize(11);
    text('W⁻', 0, 0);
    pop();
  }

  finished() {
    return this.life <= 0;
  }
}

let protons = [];
let debris = [];
let photons = [];
let collisionOccurred = false;
let collisionTimer = 0;
let resetTimer = 0;
let showLabels = true;
let detectorRings = [];

function setup() {
  createCanvas(800, 600);
  textAlign(CENTER, CENTER);
  initSimulation();
}

function initSimulation() {
  protons = [];
  debris = [];
  photons = [];
  collisionOccurred = false;
  collisionTimer = 0;
  resetTimer = 0;

  // Two protons approaching each other
  protons.push(new Proton(100, height/2, 1));
  protons.push(new Proton(width - 100, height/2, -1));

  // Detector rings (simplified CMS-like)
  detectorRings = [];
  for(let i = 1; i <= 4; i++) {
    detectorRings.push({
      radius: 80 + i * 40,
      alpha: 20 + i * 15
    });
  }
}

function draw() {
  background(245, 247, 250);

  // Draw detector infrastructure
  drawDetector();

  // Update simulation state
  if (!collisionOccurred) {
    updateAcceleration();
  } else {
    updateCollision();
  }

  // Render all elements
  drawBeamPipe();

  for (let p of protons) {
    p.update();
    p.display();
  }

  for (let i = debris.length - 1; i >= 0; i--) {
    debris[i].update();
    debris[i].display();
    if (debris[i].isDead()) {
      debris.splice(i, 1);
    }
  }

  for (let i = photons.length - 1; i >= 0; i--) {
    photons[i].update();
    photons[i].display();
    if (photons[i].isDead()) {
      photons.splice(i, 1);
    }
  }

  drawInfoPanel();

  // Reset after showing collision results
  if (collisionOccurred && debris.length === 0 && photons.length === 0) {
    resetTimer++;
    if (resetTimer > 180) {
      initSimulation();
    }
  }
}

function drawDetector() {
  push();
  translate(width/2, height/2);
  noFill();
  strokeWeight(2);

  for (let ring of detectorRings) {
    stroke(100, 100, 120, ring.alpha);
    ellipse(0, 0, ring.radius * 2);
  }

  // Inner tracker
  fill(200, 200, 210, 30);
  noStroke();
  ellipse(0, 0, 160);
  pop();
}

function drawBeamPipe() {
  stroke(180, 180, 190);
  strokeWeight(4);
  line(0, height/2, width, height/2);

  // Beam direction indicators
  fill(100);
  noStroke();
  triangle(50, height/2 - 10, 70, height/2, 50, height/2 + 10);
  triangle(width - 50, height/2 - 10, width - 70, height/2, width - 50, height/2 + 10);
}

function updateAcceleration() {
  let distance = abs(protons[0].pos.x - protons[1].pos.x);

  if (distance < 30) {
    collisionOccurred = true;
    createCollision();
  }
}

function createCollision() {
  // Create particle spray representing quarks, gluons, leptons
  let colors = [
    color(220, 50, 50),   // Red: Up quarks
    color(50, 100, 220),  // Blue: Down quarks
    color(50, 180, 80),   // Green: Gluons
    color(255, 180, 0),   // Orange: Muons
    color(180, 50, 180)   // Purple: Electrons
  ];

  let types = ['Up Quark', 'Down Quark', 'Gluon', 'Muon', 'Electron'];

  // Create jets ( sprays of particles)
  for (let angle = 0; angle < TWO_PI; angle += PI/8) {
    let count = floor(random(3, 8));
    for (let i = 0; i < count; i++) {
      let spread = random(-0.3, 0.3);
      let speed = random(2, 6);
      let typeIdx = floor(random(colors.length));
      debris.push(new DebrisParticle(
        width/2, 
        height/2, 
        angle + spread, 
        speed, 
        colors[typeIdx],
        types[typeIdx]
      ));
    }
  }

  // Create photons (neutral, high energy)
  for (let i = 0; i < 6; i++) {
    let angle = random(TWO_PI);
    photons.push(new PhotonParticle(width/2, height/2, angle));
  }

  // Remove protons
  protons = [];
}

function updateCollision() {
  collisionTimer++;
}

function drawInfoPanel() {
  fill(40);
  noStroke();
  textSize(14);
  textAlign(LEFT, TOP);

  if (!collisionOccurred) {
    text("Proton-Proton Collision Simulation", 20, 20);
    textSize(12);
    fill(80);
    text("Accelerating to 99.999% light speed...", 20, 40);
    text("Energy: 13 TeV", 20, 55);
  } else {
    text("Collision Event Detected", 20, 20);
    textSize(12);
    fill(80);
    text("New particles created from energy (E=mc²)", 20, 40);
    text("Detecting: Quarks, Leptons, Bosons", 20, 55);

    if (collisionTimer > 60 && collisionTimer < 200) {
      textAlign(CENTER, CENTER);
      fill(40);
      textSize(16);
      text("Energy → Mass", width/2, height/2 + 120);
      textSize(12);
      fill(100);
      text("High-energy collisions create fundamental particles", width/2, height/2 + 140);
    }
  }

  // Legend
  drawLegend();
}

function drawLegend() {
  let legendX = width - 150;
  let legendY = 20;

  textAlign(LEFT, TOP);
  textSize(12);
  fill(40);
  text("Particle Types:", legendX, legendY);

  let items = [
    {color: color(220, 50, 50), label: "Quarks"},
    {color: color(50, 100, 220), label: "Leptons"},
    {color: color(50, 180, 80), label: "Bosons"},
    {color: color(255, 180, 0), label: "Photons"}
  ];

  for (let i = 0; i < items.length; i++) {
    let y = legendY + 20 + i * 20;
    fill(items[i].color);
    noStroke();
    ellipse(legendX, y + 6, 10, 10);
    fill(80);
    text(items[i].label, legendX + 15, y);
  }
}

class Proton {
  constructor(x, y, direction) {
    this.pos = createVector(x, y);
    this.vel = createVector(direction * 8, 0);
    this.acc = createVector(0, 0);
    this.direction = direction;
    this.trail = [];
  }

  update() {
    // Accelerate as they approach center
    let distToCenter = abs(this.pos.x - width/2);
    if (distToCenter > 200) {
      this.vel.x *= 1.02;
    }

    // Store trail
    this.trail.push(this.pos.copy());
    if (this.trail.length > 20) {
      this.trail.shift();
    }

    this.pos.add(this.vel);
  }

  display() {
    // Draw trail
    noStroke();
    for (let i = 0; i < this.trail.length; i++) {
      let alpha = map(i, 0, this.trail.length, 0, 100);
      fill(100, 150, 255, alpha);
      let size = map(i, 0, this.trail.length, 4, 12);
      ellipse(this.trail[i].x, this.trail[i].y, size, size);
    }

    // Draw proton
    fill(100, 150, 255);
    stroke(50, 100, 200);
    strokeWeight(2);
    ellipse(this.pos.x, this.pos.y, 24, 24);

    // Quark structure indication
    fill(255, 100, 100);
    noStroke();
    ellipse(this.pos.x - 4, this.pos.y - 4, 8, 8);
    ellipse(this.pos.x + 4, this.pos.y + 4, 6, 6);
    ellipse(this.pos.x, this.pos.y, 5, 5);
  }
}

class DebrisParticle {
  constructor(x, y, angle, speed, col, type) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.fromAngle(angle).mult(speed);
    this.acc = createVector(0, 0);
    this.color = col;
    this.type = type;
    this.lifespan = 255;
    this.size = random(4, 8);
    this.trail = [];
  }

  update() {
    // Magnetic field effect - curved paths based on charge simulation
    if (this.type === 'Electron' || this.type === 'Muon') {
      this.vel.rotate(0.02);
    } else if (this.type === 'Up Quark' || this.type === 'Down Quark') {
      this.vel.rotate(-0.01);
    }

    this.vel.mult(0.98); // Slow down

    this.trail.push(this.pos.copy());
    if (this.trail.length > 10) {
      this.trail.shift();
    }

    this.pos.add(this.vel);
    this.lifespan -= 2;
  }

  display() {
    // Trail
    noStroke();
    for (let i = 0; i < this.trail.length; i++) {
      let alpha = map(i, 0, this.trail.length, 0, this.lifespan * 0.5);
      let c = color(red(this.color), green(this.color), blue(this.color), alpha);
      fill(c);
      ellipse(this.trail[i].x, this.trail[i].y, this.size * 0.6, this.size * 0.6);
    }

    // Particle
    fill(red(this.color), green(this.color), blue(this.color), this.lifespan);
    noStroke();
    ellipse(this.pos.x, this.pos.y, this.size, this.size);

    // Glow
    fill(red(this.color), green(this.color), blue(this.color), this.lifespan * 0.3);
    ellipse(this.pos.x, this.pos.y, this.size * 2, this.size * 2);
  }

  isDead() {
    return this.lifespan <= 0;
  }
}

class PhotonParticle {
  constructor(x, y, angle) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.fromAngle(angle).mult(12);
    this.lifespan = 200;
  }

  update() {
    this.pos.add(this.vel);
    this.lifespan -= 1;
  }

  display() {
    stroke(255, 200, 0, this.lifespan);
    strokeWeight(3);
    line(this.pos.x, this.pos.y, this.pos.x - this.vel.x * 2, this.pos.y - this.vel.y * 2);

    // Glow
    noStroke();
    fill(255, 220, 100, this.lifespan * 0.4);
    ellipse(this.pos.x, this.pos.y, 16, 16);
  }

  isDead() {
    return this.lifespan <= 0;
  }
}

