    {color: color(255, 180, 0), label: "Photons"}
  ];

  for (let i = 0; i < items.length; i++) {
    let y = legendY + 20 + i * 20;
    fill(items[i].color);
    noStroke();
    ellipse(legendX, y + 6, 10, 10);
    fill(80);
    text(items[i].label, legendX + 15, y);
  }
}

class Proton {
  constructor(x, y, direction) {
    this.pos = createVector(x, y);
    this.vel = createVector(direction * 8, 0);
    this.acc = createVector(0, 0);
    this.direction = direction;
    this.trail = [];
  }

  update() {
    // Accelerate as they approach center
    let distToCenter = abs(this.pos.x - width/2);
    if (distToCenter > 200) {
      this.vel.x *= 1.02;
    }

    // Store trail
    this.trail.push(this.pos.copy());
    if (this.trail.length > 20) {
      this.trail.shift();
    }

    this.pos.add(this.vel);
  }

  display() {
    // Draw trail
    noStroke();
    for (let i = 0; i < this.trail.length; i++) {
      let alpha = map(i, 0, this.trail.length, 0, 100);
      fill(100, 150, 255, alpha);
      let size = map(i, 0, this.trail.length, 4, 12);
      ellipse(this.trail[i].x, this.trail[i].y, size, size);
    }

    // Draw proton
    fill(100, 150, 255);
    stroke(50, 100, 200);
    strokeWeight(2);
    ellipse(this.pos.x, this.pos.y, 24, 24);

    // Quark structure indication
    fill(255, 100, 100);
    noStroke();
    ellipse(this.pos.x - 4, this.pos.y - 4, 8, 8);
    ellipse(this.pos.x + 4, this.pos.y + 4, 6, 6);
    ellipse(this.pos.x, this.pos.y, 5, 5);
  }
}

class DebrisParticle {
  constructor(x, y, angle, speed, col, type) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.fromAngle(angle).mult(speed);
    this.acc = createVector(0, 0);
    this.color = col;
    this.type = type;
    this.lifespan = 255;
    this.size = random(4, 8);
    this.trail = [];
  }

  update() {
    // Magnetic field effect - curved paths based on charge simulation
    if (this.type === 'Electron' || this.type === 'Muon') {
      this.vel.rotate(0.02);
    } else if (this.type === 'Up Quark' || this.type === 'Down Quark') {
      this.vel.rotate(-0.01);
    }

    this.vel.mult(0.98); // Slow down

    this.trail.push(this.pos.copy());
    if (this.trail.length > 10) {
      this.trail.shift();
    }

    this.pos.add(this.vel);
    this.lifespan -= 2;
  }

  display() {
    // Trail
    noStroke();
    for (let i = 0; i < this.trail.length; i++) {
      let alpha = map(i, 0, this.trail.length, 0, this.lifespan * 0.5);
      let c = color(red(this.color), green(this.color), blue(this.color), alpha);
      fill(c);
      ellipse(this.trail[i].x, this.trail[i].y, this.size * 0.6, this.size * 0.6);
    }

    // Particle
    fill(red(this.color), green(this.color), blue(this.color), this.lifespan);
    noStroke();
    ellipse(this.pos.x, this.pos.y, this.size, this.size);

    // Glow
    fill(red(this.color), green(this.color), blue(this.color), this.lifespan * 0.3);
    ellipse(this.pos.x, this.pos.y, this.size * 2, this.size * 2);
  }

  isDead() {
    return this.lifespan <= 0;
  }
}

class PhotonParticle {
  constructor(x, y, angle) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.fromAngle(angle).mult(12);
    this.lifespan = 200;
  }

  update() {
    this.pos.add(this.vel);
    this.lifespan -= 1;
  }

  display() {
    stroke(255, 200, 0, this.lifespan);
    strokeWeight(3);
    line(this.pos.x, this.pos.y, this.pos.x - this.vel.x * 2, this.pos.y - this.vel.y * 2);

    // Glow
    noStroke();
    fill(255, 220, 100, this.lifespan * 0.4);
    ellipse(this.pos.x, this.pos.y, 16, 16);
  }

  isDead() {
    return this.lifespan <= 0;
  }
}
